function rz(){
  _dpr=1;
  const _rsf=(OPT.resScale||100)/100;
  let rw, rh;
  if(_renderRes){
    rw=(~~(_renderRes.w*_rsf))&~1;
    rh=(~~(_renderRes.h*_rsf))&~1;
  }else{
    rw=(~~(innerWidth*_rsf))&~1;
    rh=(~~(innerHeight*_rsf))&~1;
    if(IS_MOBILE){const _maxPx=2097152;if(rw*rh>_maxPx){const _sc=Math.sqrt(_maxPx/(rw*rh));rw=(~~(rw*_sc))&~1;rh=(~~(rh*_sc))&~1}}
  }
  // Intro(splash on) only: keep cinematic ultra-wide cap.
  const _sp=document.getElementById('splash');
  const _introLocked=!!(_sp&&_sp.classList&&_sp.classList.contains('on'));
  if(_introLocked && !_renderRes){
    const maxAspect=2.33; // 21:9 cap for intro only
    if(rw/rh > maxAspect) rw = ~~(rh * maxAspect);
  }
  rw=Math.max(2,rw);rh=Math.max(2,rh);
  // ── 논리 시야(VW/VH) = rw/rh (ss 미포함). 백킹(bw/bh) = VW*ss / VH*ss. ──
  // ss=1이면 bw===rw 로 기존과 완전 동일.
  VW=rw; VH=rh;
  // Map QA and normal gameplay share the same window/resolution-scale contract.
  _ssaa=1;
  let bw=(~~(rw*_ssaa))&~1, bh=(~~(rh*_ssaa))&~1;
  bw=Math.max(2,bw); bh=Math.max(2,bh);
  const cssW=_renderRes ? '100vw' : innerWidth+'px';
  const cssH=_renderRes ? '100vh' : innerHeight+'px';
  // If nothing changed since last layout, skip DOM writes to avoid flicker
  if(bw===_lastRw && bh===_lastRh && cssW===_lastCssW && cssH===_lastCssH){
    if(GL)GL.viewport(0,0,C.width,C.height);
    if(_bGL)_bGL.viewport(0,0,bw,bh);
    return;
  }

  _lastRw=bw; _lastRh=bh;

  // 메인 캔버스 C: 백킹 픽셀(ss 적용). 오버레이 CT/burstCvs: 논리(VW/VH) 유지 (UI는 SSAA 불필요).
  if(C.width!==bw||C.height!==bh){ C.width=bw; C.height=bh }
  if(CT.width!==rw||CT.height!==rh){ CT.width=rw; CT.height=rh }
  const _bCvs=document.getElementById('burstCvs');
  if(_bCvs){ if(_bCvs.width!==rw||_bCvs.height!==rh){ _bCvs.width=rw; _bCvs.height=rh } }

  // ── 픽셀퍼펙트: CSS = CSS픽셀, left/top 0, transform 없음 ──
  C.style.position='fixed';C.style.left='0px';C.style.top='0px';C.style.transform='none';
  CT.style.position='fixed';CT.style.left='0px';CT.style.top='0px';CT.style.transform='none';
  if(_bCvs){_bCvs.style.position='fixed';_bCvs.style.left='0px';_bCvs.style.top='0px';_bCvs.style.transform='none'}

function _drawProjectileChargeLabel(x,y,r,label){
  const cy=y-r-25;
  X.save();X.globalCompositeOperation='source-over';X.globalAlpha=1;
  X.font='bold 13px "Noto Sans KR",sans-serif';X.textAlign='center';X.textBaseline='middle';
  const metrics=_chargeLabelMetrics;
  if(metrics.ctx!==X||metrics.label!==label||metrics.font!==X.font){
    metrics.width=X.measureText(label).width;metrics.ctx=X;metrics.label=label;metrics.font=X.font;
  }
  const tw=metrics.width,bw=tw+14,bh=20,bx=x-bw/2,by=cy-bh/2;
  X.fillStyle='rgba(5,8,13,.92)';X.strokeStyle='#f4f4f4';X.lineWidth=1.5;
  X.fillRect(bx,by,bw,bh);X.strokeRect(bx,by,bw,bh);
  X.fillStyle='#ffffff';X.fillText(label,x,cy);
  X.restore();
}

function drawNumStr(X,num,x,y,ci,scale){
  var s=typeof num==='number'?String(~~num):num;
  var yy=(ci||0)*_NUM_H;
  var sc=scale||1;
  var dw=~~(_NUM_W*sc),dh=~~(_NUM_H*sc);
  var gap=~~((_NUM_W-30)*sc); // 글자 간격
  var tw=s.length*gap;var ox=x-tw/2;
  for(var i=0;i<s.length;i++){
    var d=s.charCodeAt(i)-48;if(d<0||d>9)continue;
    X.drawImage(_numAtlas,d*_NUM_W,yy,_NUM_W,_NUM_H,~~(ox+i*gap),~~y,dw,dh);
  }
}

const _rawTa=t.life/t.ml;const _age=1-_rawTa;const _bSz=t.sz||22;
// 알파: 마지막 20%에서만 급격히 페이드, 그 전엔 풀 불투명
const _ta=_rawTa>0.2?1:_rawTa*5;
const _pt=Math.min(1,_age*5);
const _bn=_pt<1?1+0.5*(1-_pt)*(1-_pt)*Math.cos(_pt*Math.PI*2):1;
const _sk=_bSz>=36&&_age<0.3?(Math.sin(_age*80)*(1-_age*3.3)*3):0;
// 데미지 숫자 (sz>=28): 비트맵 폰트 렌더
if(t.sz>=28&&t._numStr){
  const _ci=t.c==='#66ddff'?2:t.c==='#dd2200'||t.c==='#cc0000'||t.c==='#ff0000'?1:0;
  const _sc=(_bSz/48)*_bn;
  X.save();X.globalAlpha=_ta;
  drawNumStr(X,t._numStr,t.x+_sk,t.y-_NUM_H*_sc/2,_ci,_sc);
  X.restore();
}else{
  // 일반 텍스트: 흰색 fill + 얇은 외곽선
  const _fSz=~~(_bSz*_bn);
  X.save();X.translate(t.x+_sk,t.y);
  X.font='900 '+_fSz+'px "Noto Sans KR","Malgun Gothic",sans-serif';
  X.globalAlpha=_ta;
  // 외곽선도 fillText(동일 GPU 경로)로 — strokeText는 별도 2D 오버레이라 GPU 모드에서 속이 비어 보임
  const _ow=Math.max(1,~~(_fSz*.06));
  X.fillStyle='#000000';
  X.fillText(t.t,-_ow,0);X.fillText(t.t,_ow,0);X.fillText(t.t,0,-_ow);X.fillText(t.t,0,_ow);
  X.fillText(t.t,-_ow,-_ow);X.fillText(t.t,_ow,-_ow);X.fillText(t.t,-_ow,_ow);X.fillText(t.t,_ow,_ow);
  X.fillStyle='#ffffff';X.fillText(t.t,0,0);
  X.restore();
}
